export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    const match = url.pathname.match(/^\/files\/([^/]+)$/);
    if (!match) return new Response("Not found", { status: 404 });
    const name = decodeURIComponent(match[1]);

    if (request.method === "PUT") {
      if (!isAuthorized(request, env)) {
        return new Response("Unauthorized", { status: 401 });
      }
      const contentType = request.headers.get("content-type") || "application/octet-stream";
      const bytes = new Uint8Array(await request.arrayBuffer());
      const description = await describeFile(env, name, contentType, bytes);
      await env.FILES.put(name, bytes, {
        httpMetadata: { contentType },
        customMetadata: { description },
      });
      return new Response(
        JSON.stringify({ name, contentType, size: bytes.length, description }),
        { headers: { "content-type": "application/json" } }
      );
    }

    if (request.method === "GET") {
      const obj = await env.FILES.get(name);
      if (!obj) return new Response("Not found", { status: 404 });
      const headers = new Headers();
      obj.writeHttpMetadata(headers);
      headers.set("etag", obj.httpEtag);
      if (obj.customMetadata && obj.customMetadata.description) {
        headers.set("x-description", obj.customMetadata.description);
      }
      return new Response(obj.body, { headers });
    }

    return new Response("Method not allowed", { status: 405 });
  },
};

function isAuthorized(request, env) {
  if (!env.API_KEY) return false;
  const headerKey = request.headers.get("x-api-key");
  const auth = request.headers.get("authorization") || "";
  const bearer = auth.replace(/^Bearer\s+/i, "");
  return headerKey === env.API_KEY || bearer === env.API_KEY;
}

async function describeFile(env, name, contentType, bytes) {
  try {
    if (contentType.startsWith("image/")) {
      const res = await env.AI.run("@cf/llava-hf/llava-1.5-7b-hf", {
        image: Array.from(bytes),
        prompt: "Describe this image in exactly one concise sentence.",
        max_tokens: 64,
      });
      return cleanOneSentence(res.description || res.response || "An uploaded image.");
    }

    if (isTextLike(contentType)) {
      const text = new TextDecoder().decode(bytes).slice(0, 4000);
      const res = await env.AI.run("@cf/meta/llama-3-8b-instruct", {
        messages: [
          { role: "system", content: "You summarize file contents in exactly one concise sentence." },
          { role: "user", content: `File name: ${name}\nContent:\n${text}` },
        ],
      });
      return cleanOneSentence(res.response || "A text file.");
    }

    const res = await env.AI.run("@cf/meta/llama-3-8b-instruct", {
      messages: [
        { role: "system", content: "You write a one-sentence plausible description of a file based only on its metadata." },
        { role: "user", content: `File name: ${name}, content-type: ${contentType}, size: ${bytes.length} bytes.` },
      ],
    });
    return cleanOneSentence(res.response || `A ${contentType} file named ${name}.`);
  } catch (err) {
    return `A ${contentType} file named "${name}" (${bytes.length} bytes).`;
  }
}

function isTextLike(contentType) {
  return (
    contentType.startsWith("text/") ||
    contentType.includes("json") ||
    contentType.includes("xml") ||
    contentType.includes("javascript") ||
    contentType.includes("csv")
  );
}

function cleanOneSentence(s) {
  const trimmed = s.trim().replace(/\s+/g, " ");
  const match = trimmed.match(/^[^.!?]*[.!?]/);
  return match ? match[0].trim() : trimmed;
}
